// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testFuzz_property(uint256 _val, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(c.MinSum() == _val);
        } else {
            assertTrue(c.MinSum() == 0);
        }
    }
}
